import path from "node:path";
import { fileURLToPath } from "node:url";

// The server runs from its bundled file in apps/api-server/dist, so these
// defaults resolve against the repository layout (locally and in Docker).
const distDir = path.dirname(fileURLToPath(import.meta.url));

/** Built website files (output of the bianco-restaurant Vite build). */
export const webDistDir =
  process.env["WEB_DIST_DIR"] ??
  path.resolve(distDir, "../../bianco-restaurant/dist/public");

/** SQL migration files generated by drizzle-kit. */
export const migrationsDir =
  process.env["MIGRATIONS_DIR"] ??
  path.resolve(distDir, "../../../lib/db/migrations");
